L.append(T(3712518,"Campuran Daging Cincang dan Lentil Dasar","Campuran daging sapi dan lentil ini tidak hanya lebih hemat biaya dibandingkan versi yang hanya berisi daging, tetapi juga lebih sehat.","5 porsi (setiap porsi untuk dua orang)",None,
["625 g daging sapi cincang","2 bawang bombai besar, dikupas dan dicincang halus","250 g lentil merah","2 sendok makan pasta tomat","1 kubus kaldu daging sapi atau sayuran rendah garam","800 ml air mendidih","2 sendok teh minyak sayur"],
["Panaskan panci antilengket besar dengan api sedang dan tambahkan minyak sayur. Masukkan bawang bombai cincang dan masak selama 6 hingga 8 menit sampai lunak.","Tambahkan lentil, kaldu, dan pasta tomat ke dalam campuran daging cincang dan bawang bombai. Didihkan, lalu kecilkan api dan didihkan perlahan selama 25 menit dengan api kecil.","Setelah matang, bagi campuran daging cincang dan lentil menjadi 5 porsi untuk digunakan."],
[g("chef","Setelah dibuat, resep serbaguna ini dapat digunakan sebagai dasar untuk membuat isian pai, kari, tumisan, atau saus pasta."),g("carb","Lentil adalah sumber utama karbohidrat dalam hidangan ini. Nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Mengganti sebagian daging sapi cincang dengan lentil membantu mengurangi kandungan fosfat, tetapi Anda tetap harus meminum pengikat fosfat bersama hidangan ini jika Anda diresepkan obat tersebut."),g("prot","Daging sapi dan lentil adalah sumber protein utama dalam hidangan ini. Hidangan ini merupakan sumber protein yang baik dan karena itu cocok bagi seseorang yang membutuhkan diet protein lebih tinggi."),g("store","Memasak dalam jumlah banyak dapat menghemat uang dan waktu, karena banyak makanan lebih murah di supermarket jika dibeli dalam jumlah besar. Porsi campuran ini dapat disimpan di lemari es selama 2 hari atau dibekukan, dalam porsi tunggal atau ganda, hingga 3 bulan. Cairkan sepenuhnya sebelum digunakan.")],
[]))
L.append(T(3763636,"Kue Wortel dari Sisa Roti","Kue ini memanfaatkan sisa roti dengan lezat untuk suguhan mewah yang rendah kalium.","10",None,
[("Kue wortel","400 g roti (putih atau gandum utuh), disobek"),("Kue wortel","100 g gula merah muda lembut"),("Kue wortel","1 telur"),("Kue wortel","100 g yoghurt penuh lemak"),("Kue wortel","50 g minyak sayur"),("Kue wortel","2 sendok teh kayu manis bubuk"),("Kue wortel","1 sendok teh soda kue"),("Kue wortel","1 sendok teh ekstrak vanila"),("Kue wortel","Kulit parut 1 jeruk"),("Kue wortel","90 g wortel, diparut"),("Kue wortel","90 g kismis"),("Kurd markisa","1 kuning telur"),("Kurd markisa","1 sendok makan gula kastor"),("Kurd markisa","100 g air perasan markisa"),("Kurd markisa","15 g mentega tawar"),("Kurd markisa","1 sendok makan tepung maizena"),("Krim mascarpone","100 g krim kental (double cream)"),("Krim mascarpone","100 g keju mascarpone, dilunakkan"),("Krim mascarpone","25 g gula halus"),("Krim mascarpone","1 sendok teh esens vanila"),("Untuk penyajian","½ sendok teh kayu manis"),("Untuk penyajian","1 sendok teh irisan tipis kulit jeruk")],
["Panaskan oven terlebih dahulu hingga 175°C / 145°C fan / gas mark 4 dan olesi lemak dan taburi tepung pada loyang persegi panjang 11” x 8.5”. Masukkan roti yang disobek ke dalam food processor dan haluskan menjadi remah halus. Tambahkan gula, telur, yoghurt, minyak, kayu manis bubuk, soda kue, dan ekstrak vanila lalu blender sampai halus. Tuang ke dalam mangkuk pencampur dan aduk kulit jeruk, wortel, dan kismis sampai tercampur rata. Masukkan adonan kue ke dalam loyang dan panggang selama 25-30 menit, sampai tusuk sate yang ditusukkan keluar bersih.","Kurd markisa: Kocok kuning telur dan gula bersama lalu sisihkan dalam mangkuk. Dalam panci berdasar tebal, panaskan perlahan air perasan markisa dan mentega hanya sampai mentega meleleh, lalu aduk tepung maizena sedikit demi sedikit sambil terus mengaduk agar tidak ada gumpalan. Angkat campuran dari api dan kocok beberapa sendok makan campuran tersebut ke dalam campuran telur di mangkuk. Terus kocok, tambahkan beberapa sendok makan campuran ke dalam campuran telur setiap kali.","Setelah kedua campuran tercampur sepenuhnya, tuang kembali ke dalam panci dan kembalikan ke api kecil hingga sedang, sambil terus diaduk agar telur tidak menggumpal atau menjadi orak-arik. Masak selama 5-8 menit sampai kurd mengental. Angkat dari api dan saring melalui saringan halus ke dalam mangkuk. Tutup dengan plastik wrap tepat di permukaan kurd dan dinginkan di lemari es setidaknya 2 jam sebelum digunakan.","Setelah kue matang dan tusuk sate yang ditusukkan keluar bersih, angkat dari oven dan biarkan dingin selama 10 menit sebelum dipindahkan ke rak kawat untuk melanjutkan pendinginan.","Krim mascarpone: Dalam mangkuk pencampur, kocok keju mascarpone dan krim kental sampai halus dan creamy. Tambahkan gula halus dan ekstrak vanila sedikit demi sedikit dan lanjutkan mengocok sampai tercampur rata.","Setelah kue dingin, potong menjadi 20 persegi. Semprotkan krim di sekeliling tepi 10 persegi kue dan isi bagian tengahnya dengan sedikit kurd. Letakkan 10 persegi yang tersisa di atasnya dan hias dengan sisa krim. Taburi dengan kayu manis dan kulit jeruk sebagai sentuhan akhir. Biarkan kue beristirahat semalaman di tempat sejuk atau bahkan di lemari es, agar rasanya berkembang."],
[g("chef","Kue wortel yang lembap dan lezat dengan icing krim keju dan kurd markisa. Selamat menikmati!"),g("carb","Roti adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Resep ini rendah kalium, jika mengikuti takaran dan ukuran penyajian yang diberikan, sehingga merupakan suguhan yang cocok bagi mereka yang dianjurkan mengurangi kalium dalam diet mereka.\nResep ini tinggi fosfat, oleh karena itu, nikmati sebagai suguhan sesekali, dan jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("prot","Resep ini rendah protein, sehingga cocok sebagai suguhan sesekali, jika Anda dianjurkan makan lebih sedikit protein."),g("cheap","Air perasan markisa mungkin sulit diperoleh. Sebagai gantinya, pertimbangkan mangga atau nanas (keduanya lebih rendah kalium daripada air perasan apel atau jeruk)."),g("gf","Gunakan roti bebas gluten"),g("health","Resep ini tinggi lemak dan mengandung garam dalam jumlah sedang dari soda kue, dan hanya boleh dinikmati sesekali, sebagai bagian dari diet seimbang yang sehat."),g("store","Setelah dimasak dan dingin, resep ini dapat disimpan dalam wadah kedap udara di lemari es hingga 3 hari.")],
[]))
L.append(T(3765080,"Salad Ayam dan Jeruk","Hidangan ringan, rendah kalori dan kalium namun kaya rasa yang menarik.","4",None,
["1 sendok teh minyak zaitun","200 g dada ayam, dipotong seukuran suapan","215 g kacang arab kalengan (130 g setelah ditiriskan) atau 150 g kacang edamame","400 g mi beras","2 selada little gem","2 jeruk, dikupas dan dipisahkan siungnya","2 jeruk nipis, diparut kulitnya",("Dressing minyak wijen","1 sendok makan minyak wijen"),("Dressing minyak wijen","Air perasan dari 2 jeruk nipis"),("Dressing minyak wijen","1 sendok makan kecap asin rendah garam"),("Dressing minyak wijen","1 sendok teh biji wijen, disangrai")],
["Panaskan minyak dalam wajan dangkal dan goreng potongan ayam dengan api sedang. Ketika hampir matang, masukkan kacang arab dan masak sampai hangat dan mulai renyah. Setelah ayam matang sempurna, angkat dan tiriskan di atas kertas dapur untuk menghilangkan kelebihan minyak (jika menggunakan kacang edamame, tambahkan nanti).","Selagi ayam dimasak, masak mi beras sesuai petunjuk kemasan, lalu tiriskan. Untuk dressing, kocok semua bahan sampai tercampur rata dan sisihkan sampai dibutuhkan.","Pisahkan daun selada, sobek yang besar menjadi dua. Campurkan selada dengan mi, siung jeruk, kulit jeruk nipis, dan kacang edamame (jika digunakan sebagai pengganti kacang arab).","Campurkan ayam dan kacang arab ke dalam salad dan bagi ke dalam empat mangkuk. Siram masing-masing porsi dengan dressing minyak wijen, lalu sajikan."],
[g("chef","Resep cepat dan mudah untuk hidangan ringan yang sehat."),g("carb","Mi beras adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Resep ini rendah kalium, meskipun menggunakan jeruk segar dan salad. Hal ini karena takarannya dijaga seminimal mungkin, sehingga pastikan Anda mengikuti takaran semua bahan dan ukuran penyajian.\nResep ini tinggi fosfat, yang berasal dari ayam dan kacang, oleh karena itu, jika Anda diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("prot","Resep ini tinggi protein, sehingga cocok bagi mereka yang dianjurkan makan lebih banyak protein, terutama mereka yang menjalani dialisis. Jika Anda dianjurkan mengurangi protein, kurangi ayam menjadi 150 g atau pilih opsi vegetarian/vegan."),g("gf","Ganti kecap asin dengan alternatif bebas gluten seperti tamari."),g("vv","Ganti ayam dengan satu kaleng 400 g kacang arab atau kacang butter yang ditiriskan."),g("health","Resep ini rendah garam, meskipun menggunakan kecap asin. Kami menyarankan menggunakan varian rendah garam, namun ini tetap tinggi garam sehingga pastikan Anda mematuhi takaran yang ditentukan."),g("store","Hidangan ini paling enak dimakan saat baru dibuat."),g("tips","Jika menggunakan kacang edamame, kacang ini dapat dibeli dalam bentuk beku. Cairkan terlebih dahulu di lemari es.")],
[]))
L.append(T(3802558,"Apel Panggang","Resep apel panggang ini menghasilkan makanan penutup buah yang mewah dan lezat yang rendah kalium dan fosfat.","4",None,
["4 apel pencuci mulut (misalnya Gala, Braeburn, Pink Lady, Cox, Golden Delicious)","50 g mentega tawar, dilunakkan","80-100 g blueberry (segar atau beku dan dicairkan)","15 g gula merah muda lembut"],
["Panaskan oven hingga 180°C / 160°C/ gas mark 4. Dengan pengeruk apel, buang bagian inti apel dan buat lubangnya sedikit lebih besar untuk diisi.","Campurkan mentega yang sudah dilunakkan, blueberry, dan gula sampai tercampur, lalu isikan ke dalam keempat rongga apel.","Letakkan apel dalam loyang pemanggang kecil dan tambahkan 4 sendok makan air ke dalam loyang.","Panggang selama 25-30 menit, tergantung ukuran apel, sampai lunak dan berkaramel. Sajikan dengan siraman krim kental atau es krim vanila kedelai."],
[g("chef","Makanan penutup apel panggang ini sangat nikmat setelah Anda menyantap panggang hari Minggu."),g("carb","Sumber utama karbohidrat dalam hidangan ini adalah apel dan gula. Nilai karbohidrat diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Dengan mengikuti takaran yang diberikan, makanan penutup ini rendah kalium dan fosfat, sehingga Anda dapat menikmatinya sebagai suguhan istimewa saat menjalani pembatasan diet."),g("prot","Makanan penutup ini rendah protein sehingga dapat dinikmati sebagai suguhan sesekali jika menjalani diet rendah protein."),g("vegan","Gunakan mentega vegan dan krim kental vegan atau es krim kedelai."),g("health","Resep ini tinggi lemak, yang berasal dari mentega dan krim. Untuk mengurangi lemak, ganti mentega dengan olesan rendah lemak atau gunakan lebih sedikit mentega (misalnya, gunakan setengah jumlahnya). Anda juga dapat mengganti krim dengan crème fraiche setengah lemak atau yoghurt kedelai tawar."),g("store","Resep ini paling enak dimakan segar."),g("tips","Apel dapat disiapkan sehari sebelumnya. Cukup tutup dan dinginkan di lemari es sampai siap dipanggang.")],
[]))
L.append(T(3815833,"Lasagna Ayam dan Sayuran","Resep ini merupakan sumber protein yang sangat baik dan penuh kebaikan tambahan dari sayuran.","4",None,
["300 g fillet paha ayam tanpa kulit dan tanpa tulang, dipotong dadu","2 bawang bombai kecil atau 1 besar, dikupas dan dicincang halus","4 siung bawang putih, dikupas dan dimemarkan","400 g tomat cincang kalengan","2 sendok teh oregano kering","9 lembar lasagna kering","1 sendok makan minyak zaitun","100 g wortel, dikupas dan dipotong dadu halus","100 g bayam",("Saus putih","20 g tepung maizena"),("Saus putih","25 g mentega tawar"),("Saus putih","150 ml kaldu ayam yang dibuat dengan ¼ kubus kaldu ayam tanpa garam"),("Saus putih","300 ml susu"),("Saus putih","Lada hitam bubuk"),("Saus putih","2 sendok teh pala bubuk"),("Saus putih","40 g mozzarella parut"),("Dressing","1 sendok makan minyak zaitun"),("Dressing","2 sendok teh cuka"),("Dressing","2 sendok teh mustard Dijon"),("Dressing","Lada hitam bubuk"),("Untuk penyajian","200 g campuran daun salad")],
["Buat saus putih dengan melelehkan mentega dalam panci kecil dengan api sedang lalu kocok tepung maizena dan pala, masak selama 2 menit. Tambahkan susu dan kaldu ayam perlahan sambil terus dikocok agar tidak menggumpal. Tetap di atas api sedang sampai mengental. Angkat dari api dan sisihkan.","Panaskan setengah minyak zaitun dalam wajan dengan api sedang-besar dan masak ayam sampai kecokelatan di seluruh sisi. Angkat dari wajan dan sisihkan. Panaskan sisa minyak dalam wajan dan masak bawang bombai dan wortel sampai lunak, tambahkan bawang putih dan oregano dan masak 2 menit lagi. Masukkan daun bayam ke dalam panci terpisah dan tuang sedikit air mendidih di atasnya. Didihkan perlahan selama 1 menit, atau sampai semua bayam layu, lalu angkat dari api. Tiriskan bayam menggunakan saringan, lalu bilas dengan air dingin dan peras kelebihan airnya. Masukkan tomat, bayam, dan ayam ke dalam wajan bersama wortel dan bawang bombai, didihkan perlahan dan masak selama 5 menit.","Panaskan oven hingga 180°C/gas mark 6. Oleskan sepertiga saus putih di dasar loyang, lalu letakkan setengah campuran ayam di atasnya. Letakkan 4 ½ lembar lasagna lalu sepertiga saus putih lainnya dan sisa campuran ayam. Dilanjutkan dengan sisa lasagna dan ditutup dengan saus putih. Taburkan mozzarella. Masak selama 40 menit.","Buat dressing dengan memasukkan semua bahan ke dalam mangkuk dan kocok bersama.","Angkat lasagna dari oven dan sajikan dengan campuran salad dan dressing."],
[g("chef","Sentuhan sehat pada lasagna klasik, resep lezat ini sempurna untuk seluruh keluarga."),g("portchild","Ukuran penyajian didasarkan pada porsi dewasa. Berikut panduan untuk anak-anak:\nBalita (usia 1-4): ¼ porsi dewasa\nAnak kecil (usia 5-9): ½ porsi dewasa\nAnak yang lebih besar (usia 10-13): ¾ porsi dewasa\nRemaja (14+): 1 porsi dewasa\n"+CH),g("carb","Lembaran lasagna adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Meskipun menggunakan beberapa bahan tinggi kalium, seperti bayam dan tomat, resep ini rendah kalium, jika mengikuti takaran dalam daftar bahan, cara memasak, dan ukuran penyajian. Karena itu, cocok bagi mereka yang dianjurkan menurunkan kalium dalam diet mereka.\nResep ini juga rendah fosfat, namun tetap mengandung sedikit fosfat, terutama dari ayam, susu, dan keju, sehingga jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk. Untuk menurunkan fosfat lebih jauh, Anda dapat mempertimbangkan mengurangi jumlah keju dalam resep."),g("prot","Resep ini tinggi protein, sehingga cocok bagi mereka yang dianjurkan makan lebih banyak protein, seperti mereka yang menjalani dialisis. Jika Anda dianjurkan makan lebih sedikit protein, Anda mungkin ingin mengurangi jumlah ayam menjadi 150 g dan mencoba menambahkan lebih banyak sayuran seperti zukini, wortel, dan brokoli."),g("energy","Jika Anda perlu menaikkan berat badan, memiliki anak yang sedang tumbuh dan membutuhkan lebih banyak kalori, atau nafsu makan Anda kurang, Anda dapat menambahkan lebih banyak mentega untuk membuat saus putih atau menggunakan susu murni untuk menambah kalori."),g("gf","Gunakan lasagna bebas gluten"),g("veg","Pertimbangkan menggunakan 300-400 g tahu atau daging kedelai untuk menggantikan ayam sebagai pilihan vegetarian."),g("vegan","Pertimbangkan menggunakan alternatif bebas susu untuk mentega, susu, dan keju."),g("health","Pertimbangkan menggunakan lembaran lasagna gandum utuh sebagai pilihan yang lebih sehat."),g("cheap","Resep ini dibuat dengan biaya serendah mungkin."),g("store","Setelah dimasak dan dingin, resep ini dapat disimpan di lemari es dan dipanaskan kembali pada hari berikutnya. Pastikan benar-benar panas saat dipanaskan kembali.")],
[]))
L.append(T(3817119,"Oat Panggang Apel","Oat panggang apel ini adalah suguhan yang mengenyangkan dan rendah kalium untuk acara-acara istimewa.","6",None,
["140 g oat bubur","1 sendok teh baking powder","1 pisang matang","100 ml susu (atau alternatif susu nabati)","1 telur besar","2 sendok makan sirup agave (atau sirup maple)","1 sendok teh esens vanila","2 sendok teh kayu manis","1 apel, diiris",("Untuk penyajian","60 g yoghurt alami"),("Untuk penyajian","10 g kelapa parut kering, disangrai"),("Opsional","250 g buah rebus (tanpa tambahan gula) seperti pir atau apel"),("Opsional","atau 400 g buah kalengan (dalam sari buah, buang sarinya), seperti persik atau pir")],
["Panaskan oven terlebih dahulu hingga 180°C / 160°C fan / gas mark 4. Olesi sedikit minyak pada wadah tahan oven. Masukkan oat dan baking powder ke dalam blender dan haluskan sampai menjadi bubuk.","Masukkan pisang, susu, telur, satu sendok makan sirup, esens vanila, dan kayu manis ke dalam blender dan blender sampai halus dan tercampur sepenuhnya. Tuang ke dalam wadah oven.","Aduk irisan apel dengan satu sendok makan sirup yang tersisa dan tata di atas wadah. Panggang selama 25 menit.","Angkat dari oven dan biarkan dingin sebentar. Sajikan dalam enam porsi dengan satu sendok yoghurt di atasnya dan taburan kelapa sangrai serta buah opsional jika diinginkan."],
[g("chef","Resep ini sangat cepat disiapkan. Dapat menjadi makanan penutup atau bahkan dimakan sebagai sarapan pada acara istimewa."),g("carb","Oat dan sirup adalah sumber utama karbohidrat dalam makanan penutup ini dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Makanan penutup ini rendah kalium, sehingga cocok pada acara istimewa bagi mereka yang dianjurkan menjalani diet rendah kalium.\nResep ini tinggi fosfat, karena oat dan baking powder. Jika Anda dianjurkan menjalani diet rendah fosfat maka sebaiknya batasi seberapa sering Anda membuat resep ini. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Resep ini rendah protein sehingga cocok bagi mereka yang dianjurkan makan lebih sedikit protein."),g("gf","Gunakan oat bebas gluten."),g("health","Anda dapat mempertimbangkan menggunakan yoghurt rendah lemak atau alternatif nabati seperti yoghurt oat atau kedelai. Anda juga mungkin ingin menyajikannya dengan buah rebus, seperti apel dan pir, atau buah kalengan seperti persik dan pir, seperti yang disarankan."),g("store","Simpan di lemari es hingga tiga hari dan panaskan kembali sebelum disajikan.")],
[]))
L.append(T(3817521,"Mi Kembang Kol dan Kale","Penuh serat, resep ini menjadi hidangan yang lezat dan mengenyangkan.","4",None,
[("Dressing","Air perasan 2 jeruk nipis atau 1 lemon"),("Dressing","2 sendok makan minyak zaitun"),("Dressing","3 sendok makan kecap asin rendah garam"),("Dressing","Sepotong jahe segar seukuran ibu jari, dikupas dan diparut halus"),("Dressing","Serpihan cabai kering, secukupnya"),("Dressing","2 siung bawang putih, dimemarkan / dicincang halus"),("Dressing","1 sendok teh sirup maple atau madu"),("Dressing","1 sendok teh minyak wijen sangrai"),("Mi","2 sendok makan minyak zaitun atau minyak sayur"),("Mi","1 kembang kol sedang, termasuk daunnya"),("Mi","200 g cavolo nero atau kale, tangkai dibuang dan daun diiris halus"),("Mi","250 g mi gandum utuh"),("Untuk penyajian","4 telur"),("Untuk penyajian","50 g kacang mete"),("Untuk penyajian","4 sendok makan kimchi")],
["Panaskan oven terlebih dahulu hingga 200°C/ 180°C fan/ gas mark 6. Pangkas daun yang layu dan tangkai dari kembang kol, cuci di bawah air dingin mengalir, lalu potong kembang kol utama menjadi kuntum dan daunnya menjadi potongan besar. Aduk kuntum dan daun dengan 1 sendok makan minyak sayur dan masukkan ke dalam oven untuk dipanggang selama 30 menit, diaduk setelah 15 menit.","Masukkan semua bahan dressing ke dalam toples selai yang kosong dan bersih lalu kocok dengan baik.","Didihkan air dalam panci besar dan, setelah mendidih, masukkan mi dan masak sesuai petunjuk kemasan (biasanya sekitar 4-5 menit). Tiriskan dengan baik dan sisihkan.","Panaskan sisa 1 sendok makan minyak sayur dalam wajan besar dengan api sedang-besar lalu masukkan cavolo nero atau kale. Masak, sambil sering diaduk, sekitar 4 menit sampai empuk.","Masukkan mi yang sudah dimasak dan kembang kol ke dalam wajan berisi cavolo nero atau kale lalu tuang dressing. Aduk rata agar terlumuri dressing. Masak beberapa menit sampai semuanya panas.","Jika disajikan dengan kacang mete, panaskan wajan kecil dengan api sedang (tanpa minyak) dan masukkan kacang mete. Masak sekitar tiga menit sampai disangrai, goyangkan wajan secara teratur agar tidak gosong. Jika Anda makan dengan telur, rebus tanpa kulit atau goreng selagi mi, cavolo nero atau kale, dan kembang kol selesai dimasak. Untuk menyajikan, tata mi, kembang kol, dan cavolo nero atau kale di piring, letakkan telur di atasnya, taburkan beberapa kacang mete dan tambahkan satu sendok makan kimchi, jika digunakan."],
[g("chef","Hidangan lezat, kaya rasa, dan sedikit pedas."),g("carb","Mi adalah sumber utama karbohidrat dalam hidangan ini dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Kacang cenderung tinggi kalium dan fosfat tetapi Anda dapat menggunakan sedikit kacang mete dalam resep ini untuk menambah kerenyahan. Mi rendah kalium sehingga memungkinkan penambahan sayuran yang tidak direbus pada hidangan ini.\nJika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Resep ini memenuhi kriteria hidangan rendah protein. Anda mungkin ingin menambahkan telur ekstra jika Anda memiliki kebutuhan protein yang lebih tinggi, tetapi hidangan ini tidak lagi menjadi hidangan rendah fosfat."),g("gf","Gunakan mi bebas gluten (misalnya soba atau mi beras) dan tamari sebagai pengganti kecap asin (pilih yang rendah garam jika bisa)."),g("veg","Periksa bahwa kimchi tidak dibuat dengan ikan atau kerang-kerangan."),g("vegan","Hilangkan telur dan gunakan sirup maple, bukan madu, dalam dressing. Periksa bahan kimchi jika digunakan."),g("cheap","Pilih mi biasa dan hilangkan tambahan opsional yang lebih mahal seperti kimchi dan kacang mete."),g("store","Dressing dapat disimpan di lemari es selama dua hari. Sisa makanan dapat ditutup dan disimpan di lemari es hingga dua hari dan dimakan dingin atau dipanaskan kembali."),g("tips","Banyak langkah dapat dilakukan sebelumnya: kembang kol dapat dipanggang, dressing dapat dibuat, dan cavolo nero dapat disiapkan, siap dimasak, sehingga saat Anda ingin makan, Anda hanya perlu memasak mi, memasak cavolo nero, dan menambahkan kembang kol yang sudah dimasak serta dressing untuk memanaskan semuanya.")],
[]))
save(8,L)
